-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 9
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 09 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 09', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 09 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-09.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Defina evento em design de interface.', 0.2, 'Evento é qualquer acontecimento detectável originado pelo usuário (toque, clique, deslize) ou pelo sistema operacional, que a interface escuta para decidir o que mudar na tela.', 'Nota cheia: define evento como ação ou acontecimento detectável (do usuário ou do sistema) que a interface reconhece e responde, com as palavras do aluno. Metade: define evento só como "toque" ou "ação do usuário", sem mencionar a resposta da interface. Zero: em branco, definição errada ou copiada sem relação com o tema.'),
      (v_atividade, 1, 2, 'Dê dois exemplos de eventos que uma tela de agendamento pode receber.', 0.4, 'Dois exemplos de eventos na tela de agendamento, como tocar no botão "Agendar", tocar em uma data do calendário, tocar em um horário livre ou deslizar para trocar de mês.', 'Nota cheia: cita dois eventos distintos e plausíveis para uma tela de agendamento, com a ação correspondente. Metade: cita um evento válido ou dois eventos sem relação clara com a tela. Zero: em branco, exemplos que não são eventos ou fora do tema.'),
      (v_atividade, 1, 3, 'Explique por que a falta de resposta imediata ao toque prejudica a confiança do usuário.', 0.4, 'Sem resposta imediata, o usuário não sabe se o toque foi registrado, repete o comando várias vezes e passa a desconfiar do aplicativo, o que gera ansiedade e quebra a confiança.', 'Nota cheia: explica que a falta de retorno faz o usuário repetir o toque, ficar inseguro e perder a confiança na tela. Metade: menciona só a repetição do toque ou só a falta de confiança, sem explicar a relação. Zero: em branco, resposta desconectada do problema do toque sem resposta.'),
      (v_atividade, 2, 1, 'Descreva o clique ou toque e sua função principal.', 0.2, 'O clique ou toque é a ação primária de ativação instantânea, usada para abrir links, acionar botões e marcar opções.', 'Nota cheia: descreve o clique ou toque como ação de ativação imediata e cita uma função (abrir link, acionar botão ou marcar opção). Metade: descreve o toque sem citar a função principal, ou cita a função sem o caráter imediato. Zero: em branco ou descrição errada.'),
      (v_atividade, 2, 2, 'Descreva o toque longo e um uso típico dele.', 0.4, 'O toque longo é pressionar e segurar por mais de meio segundo, usado para revelar menus ocultos ou opções como excluir.', 'Nota cheia: descreve o toque longo como pressionar e manter por certo tempo (cerca de meio segundo ou mais) e indica um uso típico (menu oculto, opção de exclusão). Metade: descreve o gesto sem tempo ou sem uso, ou o uso sem o gesto. Zero: em branco ou confunde com clique rápido.'),
      (v_atividade, 2, 3, 'Descreva o deslize (swipe) e o foco/hover, indicando um uso para cada um.', 0.4, 'O deslize (swipe) é arrastar o dedo pela tela, usado para trocar fotos em um carrossel, arquivar mensagens ou abrir gavetas. O foco e o hover são acionados pelo cursor sobre o elemento ou pela seleção de campos via teclado, preparando a digitação.', 'Nota cheia: descreve o deslize e o foco/hover e indica um uso correto para cada um. Metade: descreve corretamente um dos dois gestos com seu uso, ou os dois sem uso. Zero: em branco ou descrições erradas.'),
      (v_atividade, 3, 1, 'Nomeie os três canais de resposta ao usuário.', 0.2, 'Os três canais de resposta ao usuário são o visual, o sonoro e o tátil (háptico).', 'Nota cheia: nomeia os três canais (visual, sonoro e tátil ou háptico). Metade: nomeia dois canais corretos. Zero: em branco ou canais que não estão na aula.'),
      (v_atividade, 3, 2, 'Explique o que é a resposta visual e dê um exemplo para o envio do pedido.', 0.4, 'A resposta visual é a mudança percebida na tela, como cor, barra de progresso, botão afundado ou animação de carregamento. No envio do pedido, o botão pode mostrar um indicador giratório e a tela pode exibir a confirmação de sucesso.', 'Nota cheia: explica resposta visual como mudança na tela e dá exemplo aplicado ao envio do pedido (indicador de carregamento, cor do botão ou tela de sucesso). Metade: explica o conceito sem exemplo, ou dá exemplo sem o conceito. Zero: em branco ou exemplo fora do envio do pedido.'),
      (v_atividade, 3, 3, 'Explique o que é a resposta tátil e em que situação ela é útil.', 0.4, 'A resposta tátil é um pulso vibratório leve (háptica) que simula o toque de uma tecla mecânica e avisa erros críticos. Ela é útil para confirmar um toque sem exigir que o usuário olhe para a tela.', 'Nota cheia: explica a resposta tátil como vibração ou pulso e indica uma situação útil (confirmar toque sem olhar, avisar erro crítico). Metade: explica a vibração sem situação útil, ou cita situação sem explicar o conceito. Zero: em branco ou confunde com resposta sonora.'),
      (v_atividade, 4, 1, 'Cite os cinco estados visuais fundamentais de um componente interativo.', 0.2, 'Os cinco estados visuais fundamentais são padrão, hover, ativo, foco e desabilitado.', 'Nota cheia: cita os cinco estados (padrão, hover, ativo, foco e desabilitado). Metade: cita três ou quatro estados corretos. Zero: em branco ou estados que não fazem parte da aula.'),
      (v_atividade, 4, 2, 'Explique o que o estado desabilitado comunica ao usuário.', 0.4, 'O estado desabilitado comunica que o componente está bloqueado até que uma ação prévia seja feita, geralmente com opacidade reduzida (cerca de 40%) e cursor bloqueado, mostrando que faltam dados antes do clique.', 'Nota cheia: explica que o desabilitado mostra que o componente está bloqueado ou indisponível e que o usuário precisa completar algo antes, citando um sinal visual. Metade: explica só que o botão está bloqueado, sem a relação com a ação prévia. Zero: em branco ou afirma que o botão desabilitado deve reagir normalmente.'),
      (v_atividade, 4, 3, 'Diga o que deve ser ajustado no botão "Enviar" para que ele comunique corretamente a falta de dados.', 0.4, 'O botão "Enviar" deve mudar para o estado desabilitado enquanto faltarem dados (ou exibir aviso de campos obrigatórios), para que o usuário entenda por que não pode enviar.', 'Nota cheia: indica que o botão deve mudar de estado (desabilitado ou com aviso visual) enquanto houver dados faltando, com a justificativa. Metade: indica uma mudança sem explicar o motivo, ou só diz "deixar mais claro" sem propor o estado. Zero: em branco ou propõe mudar só a cor fixa, sem relação com a falta de dados.'),
      (v_atividade, 5, 1, 'Defina o estado de foco de um componente.', 0.2, 'O estado de foco é o destaque que indica qual componente está selecionado para receber a ação do teclado, normalmente com um anel visível ao redor.', 'Nota cheia: define foco como o componente selecionado para interação via teclado e indica o destaque visual. Metade: define foco sem o destaque visual ou sem a relação com o teclado. Zero: em branco ou confunde com hover.'),
      (v_atividade, 5, 2, 'Explique por que o anel de foco é obrigatório para quem navega pelo teclado.', 0.4, 'O anel de foco é obrigatório porque a pessoa que navega com a tecla Tab depende dele para saber onde está e qual campo receberá a ação.', 'Nota cheia: explica que quem usa o teclado precisa do anel para saber o campo selecionado e navegar com segurança. Metade: afirma que é importante, sem explicar por quê para quem usa o teclado. Zero: em branco ou afirma que o anel é opcional.'),
      (v_atividade, 5, 3, 'Proponha uma correção para a tela de login que resolva o problema observado.', 0.4, 'Garantir que cada campo da tela de login mostre um anel de foco visível (contorno de cor contrastante) ao receber o foco pela tecla Tab, sem removê-lo com CSS.', 'Nota cheia: propõe mostrar anel de foco visível e contrastante em todos os campos e botões da tela de login, citando a navegação por Tab. Metade: propõe destacar o campo de forma genérica, sem ligação com o anel ou com a tecla Tab. Zero: em branco ou propõe remover o destaque.'),
      (v_atividade, 6, 1, 'Diga qual estado representa o botão pressionado.', 0.2, 'O estado que representa o botão pressionado é o estado ativo.', 'Nota cheia: responde "ativo" (ou "pressionado" com o nome do estado). Metade: responde outro estado, mas com alguma relação com o toque, como hover. Zero: em branco ou estado não relacionado.'),
      (v_atividade, 6, 2, 'Explique a diferença entre o estado de hover e o estado de foco.', 0.4, 'O hover é o estado acionado quando o cursor passa sobre o elemento, típico de computadores. O foco é o destaque para navegação via teclado. Um é ligado ao ponteiro e o outro à navegação pelo teclado.', 'Nota cheia: diferencia os dois estados corretamente, indicando o hover ligado ao cursor e o foco ligado ao teclado. Metade: diferencia só um dos dois corretamente ou confunde a origem de ambos. Zero: em branco ou diz que são iguais.'),
      (v_atividade, 6, 3, 'Indique o que o botão deveria mostrar durante a ação e por que isso ajuda o usuário.', 0.4, 'Durante a ação, o botão deve mostrar um indicador de carregamento (como um giro) ou mudar seu estado, confirmando que o toque foi registrado e que o sistema está processando o pedido.', 'Nota cheia: indica que o botão deve mostrar carregamento ou mudança de estado durante a ação e explica que isso confirma o registro e evita repetições. Metade: indica o carregamento sem explicar o benefício, ou explica o benefício sem indicar o que mostrar. Zero: em branco ou propõe manter a aparência sem mudança.'),
      (v_atividade, 7, 1, 'Defina beco sem saída (dead end).', 0.2, 'Beco sem saída (dead end) é uma tela ou modal em que o usuário não encontra nenhuma forma óbvia de voltar, fechar ou avançar.', 'Nota cheia: define beco sem saída como tela ou modal sem rota óbvia de retorno, fechamento ou avanço. Metade: define como "tela sem botão" sem mencionar as três possibilidades. Zero: em branco ou definição fora do tema.'),
      (v_atividade, 7, 2, 'Explique por que o modal descrito cria um beco sem saída.', 0.4, 'O modal descrito cria um beco sem saída porque mostra a mensagem de erro e não oferece botão de fechar, cancelar ou voltar, deixando como única alternativa fechar o aplicativo à força.', 'Nota cheia: relaciona a ausência de botões no modal com a falta de saída e com a necessidade de fechar o aplicativo à força. Metade: aponta a falta de botões sem a consequência para o usuário. Zero: em branco ou atribui o problema a outra causa.'),
      (v_atividade, 7, 3, 'Proponha os botões e a regra que devem existir nesse modal para evitar o problema.', 0.4, 'O modal deve ter um botão de fechar (X) e um botão de cancelar ou de escolher outro horário. A regra é que todo modal ou mensagem de erro ofereça pelo menos uma saída clara.', 'Nota cheia: propõe pelo menos um botão de saída (fechar, cancelar ou voltar) no modal e enuncia a regra de que todo modal ou erro tenha saída clara. Metade: propõe o botão sem a regra geral, ou a regra sem botão concreto. Zero: em branco ou propõe apenas mudar a mensagem.'),
      (v_atividade, 8, 1, 'Escreva as três perguntas inconscientes do usuário na navegação.', 0.2, 'As três perguntas inconscientes do usuário são: "Onde estou agora?", "De onde eu vim?" e "Para onde posso ir?".', 'Nota cheia: escreve as três perguntas (onde estou, de onde vim, para onde posso ir), mesmo com palavras próprias. Metade: escreve duas perguntas corretas. Zero: em branco ou perguntas fora do conteúdo.'),
      (v_atividade, 8, 2, 'Explique como o título da tela responde à pergunta "Onde estou agora?".', 0.4, 'O título da tela, visível no cabeçalho, informa em qual tela ou seção o usuário está, respondendo à pergunta "Onde estou agora?".', 'Nota cheia: explica que o título visível informa a tela ou seção atual e relaciona com "Onde estou agora?". Metade: diz que o título ajuda a localizar, sem relacionar com a pergunta. Zero: em branco ou atribui essa função a outro elemento.'),
      (v_atividade, 8, 3, 'Explique como a barra de navegação ajuda a responder "Para onde posso ir?".', 0.4, 'A barra de navegação mostra as seções principais e a seção atual, respondendo "Para onde posso ir?" ao apresentar as opções reais de escolha em um toque.', 'Nota cheia: explica que a barra mostra as opções de destino disponíveis e relaciona com "Para onde posso ir?". Metade: diz que a barra serve para navegar, sem relacionar com a pergunta. Zero: em branco ou resposta sem relação com a barra.'),
      (v_atividade, 9, 1, 'Descreva a barra superior (top bar) e o que ela exibe.', 0.2, 'A barra superior (top bar) exibe o título da página atual, o botão de retornar e ações de contexto rápido.', 'Nota cheia: descreve a barra superior com título, botão de retorno e ações de contexto. Metade: cita dois dos três elementos. Zero: em branco ou descrição errada.'),
      (v_atividade, 9, 2, 'Descreva a barra inferior (bottom nav) e informe quantas seções ela deve comportar.', 0.4, 'A barra inferior (bottom nav) é comum em celulares e permite alternar entre 3 e 5 seções principais com o dedão. Para as cinco seções do aplicativo, ela comporta as cinco.', 'Nota cheia: descreve a barra inferior como navegação entre seções principais no celular e informa a faixa de 3 a 5 seções, aplicando as cinco do aplicativo. Metade: descreve a barra sem a quantidade, ou informa a quantidade sem a aplicação. Zero: em branco ou quantidade errada sem justificativa.'),
      (v_atividade, 9, 3, 'Justifique qual padrão usar no aplicativo descrito e por quê.', 0.4, 'A barra inferior, com as cinco seções, mantém as seções principais sempre visíveis e ao alcance do dedão, com a barra superior para título e retorno. A justificativa é a quantidade de seções principais e o uso no celular.', 'Nota cheia: escolhe um padrão (inferior, superior ou combinação dos dois) e justifica com a quantidade de seções e o uso no celular. Metade: escolhe um padrão e dá justificativa genérica. Zero: em branco ou escolha sem justificativa.'),
      (v_atividade, 10, 1, 'Defina trilha (breadcrumb).', 0.2, 'Trilha (breadcrumb) é a linha de navegação que mostra o caminho hierárquico percorrido, por exemplo Aula > Módulo > Atividade.', 'Nota cheia: define trilha como linha que indica o caminho hierárquico e dá um exemplo de níveis. Metade: define como caminho, sem a hierarquia. Zero: em branco ou definição fora do tema.'),
      (v_atividade, 10, 2, 'Explique o que a trilha mostra sobre a hierarquia da página.', 0.4, 'A trilha mostra a hierarquia da página, ou seja, em qual nível o usuário está e de quais níveis ele veio (da raiz até a página atual).', 'Nota cheia: explica que a trilha mostra os níveis da hierarquia, da raiz até a página atual, e a posição do usuário. Metade: diz que mostra a hierarquia sem explicar a posição. Zero: em branco ou resposta sem relação com hierarquia.'),
      (v_atividade, 10, 3, 'Explique como a trilha resolve a dificuldade de voltar vários níveis.', 0.4, 'A trilha permite voltar vários níveis com um clique direto em qualquer item (como o módulo), sem precisar clicar várias vezes em "Voltar".', 'Nota cheia: explica que basta clicar no nível desejado para voltar diretamente, evitando vários cliques em "Voltar". Metade: diz que a trilha ajuda a voltar, sem explicar o clique direto. Zero: em branco ou propõe o mesmo "Voltar" repetido.'),
      (v_atividade, 11, 1, 'Indique a transição adequada para a passagem do calendário para os horários e justifique.', 0.2, 'A passagem do calendário para os horários é um avanço para uma tela mais profunda, por isso a transição adequada é o deslizar lateral (push), que indica avanço no fluxo.', 'Nota cheia: indica deslize lateral (push) e justifica como avanço para tela mais profunda. Metade: indica push sem justificativa, ou outra transição com justificativa coerente. Zero: em branco ou transição sem relação com avanço.'),
      (v_atividade, 11, 2, 'Indique a transição adequada para o filtro de horários e explique por quê.', 0.4, 'O filtro de horários é uma subtarefa temporária, por isso a transição adequada é a subida vertical (modal), que sinaliza uma ação passageira sem trocar de tela.', 'Nota cheia: indica subida vertical (modal) e justifica como subtarefa temporária. Metade: indica modal sem justificativa, ou outra transição com justificativa coerente. Zero: em branco ou transição que não é adequada a filtro temporário.'),
      (v_atividade, 11, 3, 'Indique a transição adequada para a troca de abas "Meus pedidos" e "Histórico" e explique.', 0.4, 'A troca de abas "Meus pedidos" e "Histórico" acontece no mesmo nível hierárquico, por isso a transição adequada é o esmaecimento (fade), que é neutro e não sugere avanço nem retorno.', 'Nota cheia: indica esmaecimento (fade) e justifica pelo mesmo nível hierárquico e pela ausência de avanço. Metade: indica fade sem justificativa, ou push com justificativa de que é troca de tela. Zero: em branco ou transição sem relação com troca de abas.'),
      (v_atividade, 12, 1, 'Explique o que a transição de deslize lateral (push) indica.', 0.2, 'O deslize lateral (push) indica avanço para uma tela mais profunda ou retorno para trás no fluxo.', 'Nota cheia: explica que o push indica avanço para tela mais profunda ou retorno no fluxo. Metade: explica só o avanço ou só o retorno. Zero: em branco ou descrição errada.'),
      (v_atividade, 12, 2, 'Explique o que é a expansão de elemento e o que ela mantém visualmente.', 0.4, 'A expansão de elemento é a transição em que o próprio card clicado cresce e vira a nova tela, mantendo o foco visual intacto e a continuidade com o ponto de origem.', 'Nota cheia: explica que o próprio card se expande e vira a tela, mantendo o foco visual e a continuidade. Metade: explica a expansão sem o que ela mantém. Zero: em branco ou confunde com fade.'),
      (v_atividade, 12, 3, 'Escolha uma das duas para abrir o detalhe do pedido e justifique a escolha.', 0.4, 'Para abrir o detalhe de um pedido a partir de uma lista de cards, a melhor escolha é a expansão do elemento, pois o card clicado vira o detalhe e o usuário mantém a relação visual com a lista. O push também é aceito se o aluno justificar a escolha pelo avanço de tela.', 'Nota cheia: escolhe push ou expansão e justifica com base no conteúdo (continuidade visual ou avanço no fluxo). Metade: escolhe uma das duas sem justificativa, ou justifica com algo que não está na aula. Zero: em branco ou não escolhe nenhuma.'),
      (v_atividade, 13, 1, 'Cite os três níveis de hierarquia de telas.', 0.2, 'Os três níveis de hierarquia de telas são: nível raiz (tela de entrada ou dashboard), nível de categoria (listas, calendários e catálogos) e nível de detalhe (ficha, formulário de ação ou confirmação).', 'Nota cheia: cita os três níveis (raiz, categoria e detalhe) com a função de cada um, ou só com os nomes corretos. Metade: cita dois níveis corretos. Zero: em branco ou níveis inventados.'),
      (v_atividade, 13, 2, 'Explique qual é a regra de distância máxima para as telas principais.', 0.4, 'A regra de distância máxima é que as telas principais devem estar a no máximo dois toques de distância da tela inicial.', 'Nota cheia: informa que as telas principais devem estar a no máximo dois toques de distância. Metade: diz que a distância deve ser curta, sem o número. Zero: em branco ou número diferente sem justificativa.'),
      (v_atividade, 13, 3, 'Proponha uma nova organização para a tela de agendamento que respeite essa regra.', 0.4, 'A tela de agendamento deve ficar no nível de categoria ou na tela inicial, com acesso direto em no máximo dois toques, em vez de um submenu de quatro níveis.', 'Nota cheia: propõe colocar o agendamento no nível raiz ou de categoria, com acesso em até dois toques, e menciona a regra. Metade: propõe reduzir os níveis sem indicar o número de toques. Zero: em branco ou mantém o submenu de quatro níveis.'),
      (v_atividade, 14, 1, 'Identifique o erro de navegação observado.', 0.2, 'O erro é a inconsistência da barra de navegação: o botão "Voltar" muda de ícone e de posição a cada tela.', 'Nota cheia: identifica que o botão Voltar muda de ícone e de posição entre telas, como inconsistência. Metade: identifica só a mudança de posição ou só a de ícone. Zero: em branco ou erro não observado no caso.'),
      (v_atividade, 14, 2, 'Explique como a mudança de posição do botão "Voltar" aumenta o esforço mental do usuário.', 0.4, 'Quando o botão muda de lugar e de ícone, o usuário precisa procurá-lo e reaprender a cada tela, o que aumenta o esforço mental e a chance de se perder.', 'Nota cheia: explica que o usuário precisa procurar e reaprender o botão a cada tela, aumentando o esforço mental e a desorientação. Metade: diz que atrapalha, sem explicar o esforço mental. Zero: em branco ou resposta sem relação com o botão.'),
      (v_atividade, 14, 3, 'Diga qual deve ser a regra de consistência aplicada à barra de navegação.', 0.4, 'A regra de consistência é manter o botão de retorno no mesmo lugar e com o mesmo ícone em todas as telas, aplicando o mesmo padrão à barra de navegação.', 'Nota cheia: enuncia a regra de manter o mesmo ícone e a mesma posição em todas as telas. Metade: enuncia consistência de forma genérica, sem o ícone ou a posição. Zero: em branco ou propõe mudança sem relação com consistência.'),
      (v_atividade, 15, 1, 'Descreva o que o mapa de navegação representa no sistema.', 0.2, 'O mapa de navegação é a planta baixa do sistema: desenha as telas como caixas e as transições como linhas que as conectam.', 'Nota cheia: descreve o mapa como representação das telas (caixas) e das transições (linhas) do sistema. Metade: descreve o mapa como lista de telas, sem as transições. Zero: em branco ou definição fora do tema.'),
      (v_atividade, 15, 2, 'Explique como ele revela rotas longas e botões faltando.', 0.4, 'Ao desenhar o mapa, a equipe vê as rotas muito longas (muitos passos entre telas) e os botões que faltam, porque as conexões ficam visíveis antes do detalhe visual.', 'Nota cheia: explica que as conexões do mapa mostram rotas longas e botões faltando. Metade: cita um dos dois problemas sem explicar como o mapa os revela. Zero: em branco ou resposta sem relação com o mapa.'),
      (v_atividade, 15, 3, 'Explique por que construí-lo antes dos detalhes visuais é vantajoso.', 0.4, 'Construir o mapa antes dos detalhes visuais é vantajoso porque corrige a estrutura do planejamento antes de gastar tempo com cores e telas, o que é mais barato e evita retrabalho.', 'Nota cheia: justifica que corrigir a estrutura antes do visual evita retrabalho e custo. Metade: diz que é vantajoso sem justificar. Zero: em branco ou afirma que o visual deve vir primeiro.'),
      (v_atividade, 16, 1, 'Cite as três colunas da tabela de eventos.', 0.2, 'As três colunas da tabela de eventos são Elemento, Evento e Destino/Resposta.', 'Nota cheia: cita as três colunas corretas. Metade: cita duas corretas. Zero: em branco ou colunas inventadas.'),
      (v_atividade, 16, 2, 'Explique o que deve constar na coluna de evento.', 0.4, 'A coluna de evento deve registrar a ação esperada do usuário sobre o elemento, como toque, deslize ou foco.', 'Nota cheia: explica que a coluna registra a ação esperada (toque, deslize, foco ou similar) sobre o elemento. Metade: diz que registra "o que o usuário faz", sem exemplos ou sem relação com o elemento. Zero: em branco ou descreve a coluna de destino.'),
      (v_atividade, 16, 3, 'Preencha, em frases, uma linha da tabela para o botão "Confirmar", com o elemento, o evento e a resposta.', 0.4, 'Exemplo de linha: Elemento: botão "Confirmar"; Evento: toque; Resposta: o botão mostra o indicador de carregamento e, ao concluir, a tela de sucesso com o comprovante e o botão de retorno é exibida.', 'Nota cheia: preenche as três partes (botão "Confirmar", toque e resposta visual ou destino, como carregamento e tela de sucesso). Metade: preenche duas partes corretamente ou a resposta sem clareza. Zero: em branco ou linha sem relação com o botão.'),
      (v_atividade, 17, 1, 'Cite os quatro itens do checklist contra desorientação.', 0.2, 'Os quatro itens do checklist são: título visível, botão de retorno constante, zero becos sem saída e indicação de seleção ativa na barra inferior.', 'Nota cheia: cita os quatro itens do checklist. Metade: cita dois ou três itens corretos. Zero: em branco ou itens fora do checklist.'),
      (v_atividade, 17, 2, 'Explique o que o título visível e o botão de retorno constante garantem ao usuário.', 0.4, 'O título visível garante que o usuário saiba em qual tela está, e o botão de retorno constante garante que ele sempre tenha uma rota para voltar, no mesmo lugar em todas as telas.', 'Nota cheia: explica que o título informa a localização e o botão constante oferece a rota de volta em todas as telas. Metade: explica só um dos dois. Zero: em branco ou função não relacionada.'),
      (v_atividade, 17, 3, 'Explique como a indicação de seleção ativa na barra inferior ajuda o usuário.', 0.4, 'A aba atual da barra inferior recebe destaque com cor distinta, mostrando ao usuário em qual seção ele está e reduzindo a dúvida sobre onde se encontra.', 'Nota cheia: explica que o destaque com cor distinta indica a seção atual e reduz a dúvida de localização. Metade: diz que o destaque ajuda, sem explicar o que indica. Zero: em branco ou resposta sem relação com a barra.'),
      (v_atividade, 18, 1, 'Descreva a técnica de validar fluxos com protótipos rápidos.', 0.2, 'A técnica consiste em validar os fluxos com protótipos rápidos, testando os caminhos da navegação com os dedos sobre cartões de papel ou esquemas simples antes de programar.', 'Nota cheia: descreve a técnica como teste dos caminhos com protótipo rápido (cartões de papel ou esquema) antes de programar. Metade: descreve como "protótipo" sem o teste dos caminhos. Zero: em branco ou técnica não relacionada.'),
      (v_atividade, 18, 2, 'Explique que tipo de problema ela encontra e por que é barata.', 0.4, 'A técnica encontra becos sem saída e falhas de caminho em poucos minutos, e é barata porque usa papel ou esquemas simples, sem custo de desenvolvimento.', 'Nota cheia: indica que encontra becos sem saída (ou falhas de navegação) e que é barata por não exigir desenvolvimento. Metade: indica só o tipo de problema ou só o custo. Zero: em branco ou resposta sem relação com o problema.'),
      (v_atividade, 18, 3, 'Descreva como você aplicaria essa técnica ao aplicativo escolar, com as telas envolvidas.', 0.4, 'Eu faria cartões de papel para cada tela envolvida (Calendário, Horários e Confirmação), posicionaria os cartões na ordem do fluxo e testaria o agendamento com o dedo, verificando se o usuário chega ao fim sem ficar preso.', 'Nota cheia: descreve a aplicação com as telas do agendamento (calendário, horários, confirmação ou equivalentes) e o teste do caminho com os dedos. Metade: descreve a técnica sem citar as telas do aplicativo. Zero: em branco ou aplicação sem relação com o aplicativo escolar.'),
      (v_atividade, 19, 1, 'Defina evento e navegação.', 0.2, 'Evento é a ação do usuário ou do sistema que dispara uma resposta na interface. Navegação é a estrutura que permite mover-se entre telas, abas e seções do sistema.', 'Nota cheia: define evento (ação que dispara resposta) e navegação (estrutura para mover-se entre telas) com as palavras do aluno. Metade: define um dos dois termos corretamente. Zero: em branco ou definições erradas.'),
      (v_atividade, 19, 2, 'Defina fluxo e feedback.', 0.4, 'Fluxo é a sequência ordenada de passos para completar uma meta no aplicativo. Feedback é a resposta visual, sonora ou tátil que confirma que a ação foi registrada.', 'Nota cheia: define fluxo (sequência ordenada de passos para uma meta) e feedback (resposta que confirma o registro da ação). Metade: define um dos termos corretamente. Zero: em branco ou definições erradas.'),
      (v_atividade, 19, 3, 'Explique a diferença entre trilha (breadcrumb) e fluxo, com um exemplo de cada.', 0.4, 'A trilha (breadcrumb) mostra a hierarquia onde o usuário está, por exemplo Início > Agendamentos > Laboratório. O fluxo é a sequência de passos para uma tarefa, por exemplo escolher a data, escolher o horário e confirmar o pedido.', 'Nota cheia: diferencia trilha (caminho hierárquico, com exemplo) de fluxo (sequência de passos, com exemplo). Metade: diferencia os dois, mas sem exemplo de um deles. Zero: em branco ou confunde os conceitos.'),
      (v_atividade, 20, 1, 'Nomeie o erro de navegação ocorrido.', 0.2, 'O erro é um beco sem saída (dead end): a tela de destino não oferece nenhuma rota óbvia de retorno ou de escape.', 'Nota cheia: nomeia o erro como beco sem saída (dead end). Metade: descreve o problema sem o nome. Zero: em branco ou nome de erro não relacionado.'),
      (v_atividade, 20, 2, 'Explique o que faltou na tela de destino para o usuário escapar do erro.', 0.4, 'Faltaram a barra superior com o título da tela e o botão de retorno ou de fechar, que dariam ao usuário uma saída sem precisar fechar o aplicativo à força.', 'Nota cheia: aponta a falta de barra superior e de botão de retorno ou fechar como a causa da falta de saída. Metade: aponta só um dos dois elementos. Zero: em branco ou elemento que não estava ausente.'),
      (v_atividade, 20, 3, 'Proponha as mudanças na tela de destino que evitem o problema, com base nos padrões estudados.', 0.4, 'A tela de destino deve ter uma barra superior com título e botão de retorno (ou de fechar) visível, de acordo com o padrão de topo e a regra de zero becos sem saída.', 'Nota cheia: propõe incluir barra superior com título e botão de retorno ou fechar, citando o padrão ou a regra de zero becos sem saída. Metade: propõe um dos elementos sem a justificativa de padrão. Zero: em branco ou mudança que não resolve a ausência de saída.');
end $$;
